    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: "Mean Corpuscular Volume" (MCV) is used to classify anemias by RBC:', '["Weight", "Size (Volume)", "Shape", "Color"]', 1, 'MCV measures the average size of red blood cells, classifying them as microcytic, normocytic, or macrocytic.'),
    (v_topic_id, '2: A "Microcytic" anemia is defined by an MCV of:', '["< 80 fL", "80 to 100 fL", "> 100 fL", "< 120 fL"]', 0, 'Values below 80 fL suggest iron deficiency, thalassemia, or anemia of chronic disease.'),
    (v_topic_id, '3: Which of the following is the most common cause of "Microcytic" anemia worldwide?', '["Vitamin B12 deficiency", "Iron deficiency", "Folate deficiency", "Sickle cell disease"]', 1, 'Chronic blood loss or poor intake leads to impaired hemoglobin synthesis.'),
    (v_topic_id, '4: "Red Cell Distribution Width" (RDW) is a measure of:', '["Average RBC weight", "Variation in RBC size (anisocytosis)", "Total RBC count", "Percentage of reticulocytes"]', 1, 'A high RDW suggests multiple sizes of RBCs, often seen in early nutritional deficiencies.'),
    (v_topic_id, '5: Which microcytic anemia typically presents with a NORMAL RDW and a very high RBC count?', '["Iron deficiency", "Thalassemia minor", "Lead poisoning", "Sideroblastic anemia"]', 1, 'In thalassemia, the cells are uniformly small, resulting in a normal RDW despite the anemia.'),
    (v_topic_id, '6: "Macrocytic" anemia is defined by an MCV of:', '["< 80 fL", "80 to 100 fL", "> 100 fL", "> 120 fL"]', 2, 'Commonly due to B12/Folate deficiency or non-megaloblastic causes like alcoholism.'),
    (v_topic_id, '7: "Hypersegmented Neutrophils" on a peripheral smear are characteristic of:', '["Iron deficiency", "Megaloblastic macrocytic anemia (B12/Folate deficiency)", "Acute infection", "Thalassemia"]', 1, 'This finding suggests impaired DNA synthesis.'),
    (v_topic_id, '8: "Reticulocyte Count" is an indicator of the bone marrow''s:', '["Storage of iron", "Production of new RBCs (erythropoiesis)", "Destruction of RBCs", "White cell count"]', 1, 'A high reticulocyte count (reticulocytosis) suggests the marrow is responding to loss or hemolysis.'),
    (v_topic_id, '9: "Reticulocyte Production Index" (RPI) > 2 indicates:', '["Bone marrow failure", "Adequate marrow response to anemia", "Iron deficiency", "B12 deficiency"]', 1, 'RPI corrects the reticulocyte percentage for the degree of anemia and premature release.'),
    (v_topic_id, '10: "Serum Ferritin" is a measure of:', '["Iron currently in transport", "Total body iron stores", "Hemoglobin", "Iron absorption"]', 1, 'It is the most sensitive test for iron deficiency, though it is also an acute-phase reactant.'),
    (v_topic_id, '11: In "Iron Deficiency Anemia," the "Total Iron Binding Capacity" (TIBC) is usually:', '["Low", "High (the body is \"hungry\" for iron)", "Normal", "Zero"]', 1, 'TIBC increases as the body attempts to maximize iron transport.'),
    (v_topic_id, '12: "Transferrin Saturation" is calculated as:', '["(Serum Iron / TIBC) x 100", "Ferritin + Iron", "Hemoglobin / RBC", "TIBC - Iron"]', 0, 'Values below 15-20% suggest iron deficiency.'),
    (v_topic_id, '13: A "Mentzer Index" (MCV / RBC count) < 13 is highly suggestive of:', '["Iron deficiency", "Thalassemia", "B12 deficiency", "Hemolysis"]', 1, 'Thalassemia has a high RBC count relative to the MCV, making the index low.'),
    (v_topic_id, '14: "Haptoglobin" levels are _____ in cases of INTRAVASCULAR hemolysis.', '["Increased", "Decreased (it binds to released hemoglobin and is cleared)", "Normal", "Variable"]', 1, 'Free hemoglobin binds to haptoglobin, lowering the measured serum level.'),
    (v_topic_id, '15: "Schistocytes" (helmet cells) on a smear indicate:', '["Iron deficiency", "Microangiopathic Hemolytic Anemia (MAHA) like TTP or HUS", "Liver disease", "Sickle cell trait"]', 1, 'Mechanical shearing of RBCs as they pass through fibrin strands.'),
    (v_topic_id, '16: "Target Cells" (codocytes) are classically seen in:', '["Thalassemia, Liver disease, and Asplenia", "Iron deficiency only", "B12 deficiency", "Leukemia"]', 0, 'They result from a high surface-area-to-volume ratio.'),
    (v_topic_id, '17: "Howell-Jolly Bodies" are remnants of RBC _____ and indicate _____:', '["RNA; infection", "DNA (nuclear remnants); functional or surgical asplenia", "Iron; thalassemia", "Proteins; hemolysis"]', 1, 'The spleen normally removes these remnants from the circulation.'),
    (v_topic_id, '18: "Basophilic Stippling" of RBCs is a classic finding in:', '["Iron deficiency", "Lead poisoning", "Folate deficiency", "Scurvy"]', 1, 'It represents coarse granules of ribosomal RNA.'),
    (v_topic_id, '19: "Bite Cells" and "Heinz Bodies" are characteristic of:', '["G6PD Deficiency during oxidative stress", "Sickle cell disease", "Hereditary Spherocytosis", "Myelofibrosis"]', 0, 'Heinz bodies are denatured hemoglobin; bite cells are what remain after the spleen "bites" them out.'),
    (v_topic_id, '20: "Hereditary Spherocytosis" presents with an INCREASED:', '["MCV", "MCHC (Mean Corpuscular Hemoglobin Concentration)", "RDW", "Haptoglobin"]', 1, 'Cells lose surface area and become compact/dense, raising the MCHC.'),
    (v_topic_id, '21: "Direct Antiglobulin Test" (Direct Coombs) is used to detect:', '["Iron", "Antibodies or complement bound directly to the RBC surface", "Serum antibodies", "Bilirubin"]', 1, 'A positive test suggests Autoimmune Hemolytic Anemia (AIHA).'),
    (v_topic_id, '22: "Indirect Antiglobulin Test" (Indirect Coombs) is used to detect:', '["Bound antibodies", "Free-floating antibodies in the patient''s serum (pre-transfusion screening)", "Iron", "Glucose"]', 1, 'Commonly used in cross-matching blood.'),
    (v_topic_id, '23: "Erythrocyte Sedimentation Rate" (ESR) is a non-specific marker of:', '["Liver function", "Inflammation", "Kidney failure", "Blood type"]', 1, 'Inflammatory proteins (like fibrinogen) make RBCs stick together and fall faster.'),
    (v_topic_id, '24: A "Leukemoid Reaction" is an extreme elevation of WBCs (> 50,000) due to:', '["Leukemia", "Severe infection or stress (not malignant)", "Anemia", "Dehydration"]', 1, 'It can be distinguished from CML by a high LAP score.'),
    (v_topic_id, '25: "Leukocyte Alkaline Phosphatase" (LAP) score is LOW in which condition?', '["Infection", "Chronic Myelogenous Leukemia (CML)", "Polycythemia vera", "Pregnancy"]', 1, 'CML neutrophils are malignant and lack this enzyme.'),
    (v_topic_id, '26: "Auer Rods" in a blast cell on a smear are diagnostic of:', '["ALL", "AML (Acute Myeloid Leukemia)", "CLL", "CML"]', 1, 'They are needle-like inclusions formed by the fusion of azurophilic granules.'),
    (v_topic_id, '27: "Smudge Cells" are the classic finding in which leukemia?', '["AML", "ALL", "CLL (Chronic Lymphocytic Leukemia)", "CML"]', 2, 'Fragile lymphocytes burst during the preparation of the slide.'),
    (v_topic_id, '28: "Eosinophilia" (high eosinophil count) is commonly caused by:', '["Bacteria", "Parasites and Allergic reactions", "Viruses", "Iron deficiency"]', 1, 'Mnemonic: NAAACP (Neoplasm, Addison''s, Allergy, Asthma, Collagen vascular disease, Parasites).'),
    (v_topic_id, '29: "Basophilia" is rare but is a classic clue for:', '["Infection", "Myeloproliferative disorders (like CML)", "Anemia", "Liver failure"]', 1, 'It is often the first sign of CML in some patients.'),
    (v_topic_id, '30: "Neutrophilic Leukocytosis" with a "Left Shift" means:', '["High WBC with many immature forms like bands", "Low WBC", "High lymphocytes", "Abnormal shape"]', 0, 'This suggests an acute bacterial infection or inflammation.'),
    (v_topic_id, '31: "Atypical Lymphocytes" (Downey cells) are characteristic of:', '["Bacterial pneumonia", "Infectious Mononucleosis (EBV)", "Iron deficiency", "Thalassemia"]', 1, 'These are reactive T-cells responding to the viral infection.'),
    (v_topic_id, '32: "Pancytopenia" is the simultaneous reduction of:', '["WBC and Platelets", "RBC, WBC, and Platelets", "RBC and Hemoglobin", "Sodium and Potassium"]', 1, 'Often suggests bone marrow failure or splenic sequestration.'),
    (v_topic_id, '33: "Aplastic Anemia" is a cause of pancytopenia where the bone marrow biopsy shows:', '["Hypercellularity", "Hypocellularity (mostly fat)", "Fibrosis", "Tumor cells"]', 1, 'The marrow has "failed" to produce cells.'),
    (v_topic_id, '34: "Thrombocytopenia" is defined as a platelet count below:', '["450,000 /uL", "150,000 /uL", "100,000 /uL", "50,000 /uL"]', 1, 'Spontaneous bleeding usually doesn''t occur until platelets are < 20,000.'),
    (v_topic_id, '35: "Pseudothrombocytopenia" is a laboratory artifact caused by:', '["Platelet clumping in EDTA-collected blood", "Actual low platelets", "High WBC", "Cold"]', 0, 'Redrawing the blood in a citrate tube will reveal a normal count.'),
    (v_topic_id, '36: "Prothrombin Time" (PT) measures the _____ pathway and is used to monitor _____:', '["Intrinsic; Heparin", "Extrinsic; Warfarin", "Common; Aspirin", "Intrinsic; Warfarin"]', 1, 'PT/INR is the standard monitoring tool for Vitamin K antagonists.'),
    (v_topic_id, '37: "Activated Partial Thromboplastin Time" (aPTT) measures the _____ pathway and is used to monitor _____:', '["Extrinsic; Warfarin", "Intrinsic; Unfractionated Heparin", "Common; LMWH", "Extrinsic; Heparin"]', 1, 'LMWH usually does not require aPTT monitoring.'),
    (v_topic_id, '38: "INR" (International Normalized Ratio) was developed to:', '["Standardize PT results across different laboratories", "Measure PTT", "Calculate RBC size", "Check liver function only"]', 0, 'It adjusts the PT for the sensitivity of the thromboplastin used.'),
    (v_topic_id, '39: A "Mixing Study" that CORRECTS the PTT suggests:', '["An inhibitor (like Lupus Anticoagulant)", "A Factor Deficiency (like Hemophilia A or B)", "Heparin effect", "Laboratory error"]', 1, 'Adding normal plasma provides the missing factors.'),
    (v_topic_id, '40: A "Mixing Study" that does NOT correct the PTT suggests:', '["Factor deficiency", "Presence of a factor inhibitor (e.g., Lupus Anticoagulant or anti-factor VIII antibodies)", "Normal blood", "Vitamin K deficiency"]', 1, 'The inhibitor in the patient''s blood "neutralizes" the factors in the normal plasma.'),
    (v_topic_id, '41: "Hemophilia A" is a deficiency of Factor _____, while "Hemophilia B" is a deficiency of Factor _____:', '["VIII; IX", "IX; VIII", "X; V", "XI; XII"]', 0, 'Both cause an isolated elevation in PTT.'),
    (v_topic_id, '42: "von Willebrand Disease" (vWD) is the most common inherited bleeding disorder; it often presents with an elevated:', '["PT", "Bleeding Time (or PFA-100) and sometimes PTT", "INR", "RBC count"]', 1, 'vWF is needed for platelet adhesion and stabilizes Factor VIII.'),
    (v_topic_id, '43: "Disseminated Intravascular Coagulation" (DIC) is characterized by:', '["High Platelets", "Elevated PT, PTT, and D-dimer, with Low Platelets and Fibrinogen", "Low PT", "Normal smear"]', 1, 'It involves systemic activation of both coagulation and fibrinolysis.'),
    (v_topic_id, '44: "D-dimer" is a specific degradation product of:', '["Fibrinogen", "Cross-linked Fibrin", "Platelets", "Albumin"]', 1, 'Its presence indicates that a clot was formed and is now being broken down.'),
    (v_topic_id, '45: "Vitamin K Deficiency" initially causes an elevation in _____ because Factor _____ has the shortest half-life.', '["PT; VII", "PTT; VIII", "Bleeding time; X", "INR; II"]', 0, 'Factor VII is the first to fall.'),
    (v_topic_id, '46: "Bleeding Time" measures:', '["Coagulation factors", "Platelet function and interaction with the vessel wall", "RBC durability", "Heparin effect"]', 1, 'It is largely replaced now by the PFA-100 test.'),
    (v_topic_id, '47: "Hypercoagulability" (Thrombophilia) screening includes testing for:', '["Factor V Leiden and Protein C/S deficiency", "Iron deficiency", "B12 deficiency", "Hemophilia"]', 0, 'Factor V Leiden is the most common inherited cause of venous thrombosis in Caucasians.'),
    (v_topic_id, '48: "Hemoglobin A1c" measures average blood glucose over the past:', '["24 hours", "1 week", "2 to 3 months", "1 year"]', 2, 'It reflects the glucose attached to hemoglobin for the lifespan of the RBC.'),
    (v_topic_id, '49: "Polycythemia" is an increase in:', '["WBCs", "RBCs (Hematocrit)", "Platelets", "Plasma volume"]', 1, 'It can be primary (Polycythemia Vera) or secondary (Hypoxia/Smoking).'),
    (v_topic_id, '50: "Relative Polycythemia" is caused by:', '["Excess RBC production", "Dehydration (decreased plasma volume)", "Smoking", "High altitude"]', 1, 'The RBC mass is normal, but it is concentrated.'),
    (v_topic_id, '51: "Bence-Jones Proteins" in the urine are:', '["Albumin", "Free light chains (associated with Multiple Myeloma)", "Glucose", "Blood"]', 1, 'They are not detected by standard urine dipstick protein tests.'),
    (v_topic_id, '52: "Rouleaux formation" of RBCs (stack of coins) on a smear is characteristic of:', '["Multiple Myeloma (due to high paraproteins)", "Iron deficiency", "Malaria", "Sickle cell"]', 0, 'High protein levels reduce the repulsive charges between RBCs.'),
    (v_topic_id, '53: "M-Spike" on Serum Protein Electrophoresis (SPEP) indicates:', '["Liver disease", "Monoclonal Gammopathy (e.g., MGUS or Multiple Myeloma)", "Infection", "Dehydration"]', 1, 'It represents a large population of a single type of immunoglobulin.'),
    (v_topic_id, '54: "Beta-2 Microglobulin" is a prognostic marker for:', '["Heart failure", "Multiple Myeloma and Lymphoma", "Diabetes", "Kidney stones"]', 1, 'Higher levels correlate with a higher tumor burden.'),
    (v_topic_id, '55: "Hypercalcemia" in Multiple Myeloma is due to:', '["Excess Vitamin D", "Osteoclast activation and bone destruction", "Renal failure", "High intake"]', 1, 'Mnemonic: CRAB (Calcium, Renal failure, Anemia, Bone lesions).'),
    (v_topic_id, '56: "Burrkitt Lymphoma" cells classically show a _____ appearance on a smear.', '["Starry sky", "Smudge", "Owl eye", "Popcorn"]', 0, 'This is an architectural pattern seen on tissue biopsy (macrophages among small lymphocytes).'),
    (v_topic_id, '57: "Reed-Sternberg Cells" (Owl-eye cells) are diagnostic of:', '["Non-Hodgkin Lymphoma", "Hodgkin Lymphoma", "AML", "CLL"]', 1, 'They are large, multinucleated B-cells.'),
    (v_topic_id, '58: "G6PD Deficiency" is an X-linked disorder that causes hemolysis when the patient is exposed to:', '["Cold", "Oxidative stress (e.g., Fava beans, Sulfa drugs, Infection)", "Exercise", "Sugar"]', 1, 'Cells lack the ability to protect themselves from free radicals.'),
    (v_topic_id, '59: "Hemoglobin Electrophoresis" is used to diagnose:', '["Iron deficiency", "Hemoglobinopathies like Sickle Cell Disease and Thalassemia", "Leukemia", "Infection"]', 1, 'It separates different types of hemoglobin (A, A2, F, S, C).'),
    (v_topic_id, '60: "Hemoglobin F" (Fetal Hb) is the predominant form in:', '["Adults", "Newborns (until ~6 months of age)", "Patients with iron deficiency", "None"]', 1, 'It has a higher affinity for oxygen than HbA.'),
    (v_topic_id, '61: "Sickle Cell Trait" (HbAS) is usually:', '["Lethal", "Asymptomatic (normal CBC and smear)", "Microcytic", "Associated with severe pain"]', 1, 'Patients only have one copy of the S gene and usually do not sickle except in extreme conditions.'),
    (v_topic_id, '62: "Erythropoietin" (EPO) levels are _____ in Polycythemia Vera.', '["High", "Low (suppressed by high RBC mass)", "Normal", "Variable"]', 1, 'PV is a primary marrow disorder; secondary polycythemia (hypoxia) has high EPO.'),
    (v_topic_id, '63: "Thrombocytosis" (high platelets) can be "Essential" (malignant) or "Reactive" (due to):', '["Infection, Inflammation, or Iron deficiency", "Alcoholism", "B12 deficiency", "Liver failure"]', 0, 'Iron deficiency is a very common cause of reactive thrombocytosis.'),
    (v_topic_id, '64: "Hyperviscosity Syndrome" (blurred vision, headache, stroke) is a risk in:', '["Severe anemia", "Waldenstr\u00f6m Macroglobulinemia and Polycythemia Vera", "Hemophilia", "Diabetes"]', 1, 'Excess cells or IgM protein make the blood too "thick" to flow.'),
    (v_topic_id, '65: "Cold Agglutinins" are antibodies (usually IgM) that cause RBC clumping in:', '["Warm weather", "The cold (e.g., ears, nose, fingers)", "The liver", "The brain"]', 1, 'Often seen after Mycoplasma pneumoniae infection.'),
    (v_topic_id, '66: "C-Reactive Protein" (CRP) is produced by the _____ and is a _____ marker of inflammation than ESR.', '["Kidneys; slower", "Liver; faster/more sensitive", "Heart; better", "Bone; worse"]', 1, 'CRP levels rise and fall more rapidly than ESR.'),
    (v_topic_id, '67: "Procalcitonin" is a lab marker used to distinguish:', '["Bacterial from Viral/Non-infectious inflammation", "Heart from Lung disease", "Iron from B12 deficiency", "Male from Female blood"]', 0, 'High levels are strongly suggestive of bacterial infection.'),
    (v_topic_id, '68: "Absolute Neutrophil Count" (ANC) < 500 /uL defines severe:', '["Anemia", "Neutropenia (high risk for life-threatening infection)", "Thrombocytopenia", "Leukocytosis"]', 1, 'ANC = WBC count x (%Neutrophils + %Bands).'),
    (v_topic_id, '69: "Metamyelocytes" and "Myelocytes" in the peripheral blood indicate:', '["A normal smear", "A \"Left Shift\" or marrow stress/malignancy", "Liver disease", "Iron deficiency"]', 1, 'These are immature myeloid precursors.'),
    (v_topic_id, '70: "Blast" cells on a smear are ALWAYS:', '["Normal in children", "Abnormal (suggestive of Acute Leukemia if > 20%)", "A sign of infection", "Benign"]', 1, 'Blasts are the most immature cells in the myeloid/lymphoid lineage.'),
    (v_topic_id, '71: "Ristocetin Cofactor Assay" is used to test:', '["Platelet count", "von Willebrand Factor function", "Factor VIII", "Heparin"]', 1, 'Ristocetin induces platelet agglutination in the presence of vWF.'),
    (v_topic_id, '72: "Antithrombin III" deficiency is a hypercoagulable state where _____ may not work effectively.', '["Warfarin", "Heparin", "Aspirin", "Clopidogrel"]', 1, 'Heparin requires AT-III to exert its anticoagulant effect.'),
    (v_topic_id, '73: "Protein C" and "Protein S" are natural:', '["Pro-coagulants", "Anticoagulants (that inhibit Factors Va and VIIIa)", "Antibodies", "Vitamins"]', 1, 'Deficiency leads to a high risk of thrombosis.'),
    (v_topic_id, '74: "Warfarin-induced Skin Necrosis" is a risk in patients with:', '["Iron deficiency", "Protein C deficiency (Warfarin depletes Protein C faster than factors II, IX, X)", "Diabetes", "High salt intake"]', 1, 'A transient hypercoagulable state occurs when Warfarin is started.'),
    (v_topic_id, '75: "Lupus Anticoagulant" ironically causes:', '["Bleeding", "Thrombosis (clotting) in vivo, despite prolonging the PTT in vitro", "Anemia", "Leukocytosis"]', 1, 'It is part of the Antiphospholipid Syndrome.'),
    (v_topic_id, '76: "Hemoglobin A2" elevation is a diagnostic clue for:', '["Alpha-Thalassemia", "Beta-Thalassemia Minor", "Sickle cell", "Iron deficiency"]', 1, 'The body produces more HbA2 (\u03b12\u03b42) because it cannot make enough beta chains.'),
    (v_topic_id, '77: "Prussian Blue" stain is used to visualize _____ in the marrow or cells.', '["Sugar", "Iron (hemosiderin)", "Proteins", "Bacteria"]', 1, 'Used to identify sideroblasts.'),
    (v_topic_id, '78: "Ringed Sideroblasts" in the bone marrow suggest:', '["Iron deficiency", "Sideroblastic Anemia (e.g., from Lead, Alcohol, or Myelodysplasia)", "Thalassemia", "B12 deficiency"]', 1, 'Iron accumulates in the mitochondria of RBC precursors.'),
    (v_topic_id, '79: "Schilling Test" was historically used to determine the cause of:', '["Iron deficiency", "Vitamin B12 malabsorption (e.g., Pernicious Anemia)", "Folate deficiency", "G6PD deficiency"]', 1, 'It is now largely replaced by antibody testing (anti-intrinsic factor).'),
    (v_topic_id, '80: "Intrinsic Factor" (IF) is produced by _____ and is necessary for _____ absorption.', '["Liver; Iron", "Gastric Parietal Cells; Vitamin B12", "Pancreas; Fat", "Salivary glands; Sugar"]', 1, 'B12-IF complex is absorbed in the terminal ileum.'),
    (v_topic_id, '81: "Homocysteine" and "Methylmalonic Acid" (MMA) levels are both HIGH in:', '["Folate deficiency", "Vitamin B12 deficiency", "Iron deficiency", "Normal aging"]', 1, 'In Folate deficiency, ONLY homocysteine is high; MMA remains normal.'),
    (v_topic_id, '82: "Hemolysis" laboratory triad: Increased LDH, Increased Unconjugated Bilirubin, and:', '["Increased Ferritin", "Decreased Haptoglobin", "High WBC", "Normal pH"]', 1, 'LDH and bilirubin are released from destroyed RBCs.'),
    (v_topic_id, '83: "Teardrop Cells" (dacrocytes) are classic for:', '["Iron deficiency", "Myelofibrosis (bone marrow is replaced by scar tissue)", "B12 deficiency", "Asthma"]', 1, 'Cells are "squeezed" as they exit the fibrotic marrow.'),
    (v_topic_id, '84: "Dohle Bodies" in neutrophils are seen in:', '["Leukemia", "Severe infections, burns, or trauma", "Anemia", "Normal smears"]', 1, 'They are light blue peripheral inclusions representing rough ER.'),
    (v_topic_id, '85: "Toxic Granulation" in neutrophils is a sign of:', '["Malignancy", "Severe bacterial infection/sepsis", "Viral infection", "Lead poisoning"]', 1, 'Prominent purple-black granules in the cytoplasm.'),
    (v_topic_id, '86: "Erythrocyte Porphyrin" levels are HIGH in:', '["Iron deficiency and Lead poisoning", "B12 deficiency", "Thalassemia", "Hemolysis"]', 0, 'Used as a screening tool in children.'),
    (v_topic_id, '87: "Malaria" can be diagnosed by seeing _____ inside the RBCs on a smear.', '["Bacteria", "Parasites (e.g., rings, gametocytes)", "Sugar", "Fat"]', 1, 'Thick and thin smears are used.'),
    (v_topic_id, '88: "Babesiosis" shows a characteristic _____ appearance inside the RBC.', '["Ring", "Maltese Cross", "Dot", "Star"]', 1, 'Transmitted by the same tick as Lyme disease.'),
    (v_topic_id, '89: "Mean Corpuscular Hemoglobin" (MCH) measures the:', '["Total RBC count", "Average amount of hemoglobin in each RBC", "RBC size", "RDW"]', 1, 'MCH = Hemoglobin / RBC count.'),
    (v_topic_id, '90: "Hypochromic" RBCs have a pale center that is larger than _____ the diameter of the cell.', '["1/10", "1/3", "1/2", "3/4"]', 1, 'This indicates low hemoglobin content (e.g., Iron deficiency).'),
    (v_topic_id, '91: "Hyperchromic" is a term rarely used because RBCs cannot be "over-filled" with hemoglobin, except in:', '["Iron deficiency", "Spherocytosis", "B12 deficiency", "Lead poisoning"]', 1, 'Spherocytes look dark and lack central pallor.'),
    (v_topic_id, '92: "Anisocytosis" is seen on a smear when the _____ is high.', '["MCV", "RDW", "MCHC", "Hb"]', 1, 'It means the cells vary significantly in size.'),
    (v_topic_id, '93: "Poikilocytosis" is seen on a smear when the cells vary in:', '["Size", "Shape", "Color", "Number"]', 1, 'Example: Schistocytes, Spherocytes, and Target cells all on one slide.'),
    (v_topic_id, '94: "Burr Cells" (echinocytes) are seen in:', '["Renal failure (Uremia) and Liver disease", "Iron deficiency", "Lead poisoning", "Thalassemia"]', 0, 'They have small, regular projections from the cell surface.'),
    (v_topic_id, '95: "Acanthocytes" (spur cells) have large, irregular projections and are seen in:', '["Abetalipoproteinemia and Liver disease", "Kidney failure", "Anemia", "Infection"]', 0, 'Associated with lipid membrane abnormalities.'),
    (v_topic_id, '96: "Cold Agglutinin" titers are elevated in pneumonia caused by:', '["Streptococcus", "Mycoplasma pneumoniae", "Legionella", "Klebsiella"]', 1, 'These antibodies can cause a transient hemolytic anemia.'),
    (v_topic_id, '97: "Pelger-Huet Anomaly" is a condition where neutrophils are _____ and is a sign of _____:', '["Hypersegmented; B12 deficiency", "Bi-lobed (spectacle-shaped); Myelodysplasia or benign inheritance", "Absent; infection", "Enlarged; cancer"]', 1, 'In myelodysplasia, it is called "Pseudo-Pelger-Huet."'),
    (v_topic_id, '98: "Fibrinogen" levels fall in which condition?', '["Infection", "DIC (due to consumption)", "Early pregnancy", "Liver failure only"]', 1, 'Fibrinogen is consumed to make clots in DIC.'),
    (v_topic_id, '99: "Antithrombin III" levels can be decreased in:', '["Nephrotic Syndrome (lost in urine) and DIC (consumed)", "Iron deficiency", "Thalassemia", "Obesity"]', 0, 'Low AT-III leads to heparin resistance and thrombosis.'),
    (v_topic_id, '100: "Factor V Leiden" is a mutation that makes Factor V resistant to inactivation by:', '["Warfarin", "Activated Protein C", "Antithrombin III", "Heparin"]', 1, 'This leads to a pro-thrombotic state.');
